/** Produced values retain their source; explicit VALUES and request bindings retain their supplied authority. */
class LmdbLanguageFilterBindingIdentityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:language-binding:> ";
	private static final String PROJECT = "SELECT ?s ?o (LANG(?o) AS ?language) WHERE { ";

	static Stream<Arguments> cases() {
		List<String> bodies = List.of(
				"?s :label ?o FILTER(?o = \"abc\"@%s)",
				"?s :label ?o FILTER(\"abc\"@%s = ?o)",
				"?s :label ?o FILTER(?o IN (\"abc\"@%s))",
				"?s :label ?o FILTER(?o = \"abc\"@%s || ?o = \"other\"@%s)",
				"?s :label ?o BIND(?o AS ?alias) FILTER(?alias = \"abc\"@%s)",
				"{ ?s :label ?o } UNION { ?s :other ?o } FILTER(?o = \"abc\"@%s)",
				"?s :marker ?marker OPTIONAL { ?s :label ?o } FILTER(?o = \"abc\"@%s)",
				"?s :label ?o FILTER(?o = \"abc\"@%s) FILTER(EXISTS { ?s :marker ?marker })",
				"?s :label ?o FILTER(sameTerm(?o, \"abc\"@%s))",
				"VALUES ?o { \"abc\"@%s } ?s :label ?o FILTER(?o = \"abc\"@%s)");
		return Stream.of(new String[] { "en", "EN" }, new String[] { "EN", "en" },
				new String[] { "en-gb", "EN-GB" })
				.flatMap(tags -> Stream.concat(IntStream.range(0, bodies.size())
						.mapToObj(index -> Arguments.of(tags[0], tags[1],
								PROJECT + bodies.get(index).formatted(tags[1], tags[1]) + " }", index)),
						Stream.of(Arguments.of(tags[0], tags[1], PROJECT + "?s :label ?o }", 10))));
	}

	@ParameterizedTest
	@MethodSource("cases")
	void preservesTheActualBindingSource(String storedTag, String queryTag, String query,
			int shape, @TempDir Path directory) {
		SailRepository lmdb = new SailRepository(new LmdbStore(directory.toFile()));
		lmdb.init();
		try {
			try (RepositoryConnection connection = lmdb.getConnection()) {
				connection.begin();
				connection.add(VF.createIRI("urn:language-binding:s1"), VF.createIRI("urn:language-binding:label"),
						VF.createLiteral("abc", storedTag));
				connection.add(VF.createIRI("urn:language-binding:s2"), VF.createIRI("urn:language-binding:label"),
						VF.createLiteral("other", storedTag));
				connection.add(VF.createIRI("urn:language-binding:s3"), VF.createIRI("urn:language-binding:other"),
						VF.createLiteral("abc", storedTag));
				connection.add(VF.createIRI("urn:language-binding:s1"), VF.createIRI("urn:language-binding:marker"),
						VF.createLiteral("marker"));
				connection.commit();
			}
			String outputTag = shape >= 9 ? queryTag : storedTag;
			List<String> expected = new ArrayList<>();
			expected.add(row("s1", "abc", outputTag));
			if (shape == 3) {
				expected.add(row("s2", "other", outputTag));
			} else if (shape == 5) {
				expected.add(row("s3", "abc", outputTag));
			}
			Collections.sort(expected);
			assertEquals(expected, rows(lmdb, query, queryTag, shape == 10),
					"stored producers and explicit input bindings own their respective output representation");
		} finally {
			lmdb.shutDown();
		}
	}

	private static String row(String subject, String label, String language) {
		return "language=" + NTriplesUtil.toNTriplesString(VF.createLiteral(language))
				+ "|o=" + NTriplesUtil.toNTriplesString(VF.createLiteral(label, language))
				+ "|s=<urn:language-binding:" + subject + ">";
	}

	private static List<String> rows(SailRepository repository, String query, String queryTag,
			boolean externalBinding) {
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery prepared = connection.prepareTupleQuery(PREFIX + query);
			if (externalBinding) {
				prepared.setBinding("o", VF.createLiteral("abc", queryTag));
			}
			List<String> rows = new ArrayList<>();
			try (var result = prepared.evaluate()) {
				while (result.hasNext()) {
					BindingSet row = result.next();
					List<String> values = new ArrayList<>();
					for (String name : new TreeSet<>(row.getBindingNames())) {
						Value value = row.getValue(name);
						values.add(name + "=" + NTriplesUtil.toNTriplesString(value));
					}
					rows.add(String.join("|", values));
				}
			}
			Collections.sort(rows);
			return rows;
		}
	}
}
